import {figuresCartanWeights} from './figures-cartan-1913.mjs';
import {exceptionalWeightOrbits,orbitLabelLatex,fundamentalWeightCoordinates} from './cartan-1913-weight-data.mjs';
const m=String.raw;
const foot=t=>`<p class="author-footnote"><strong>Author’s footnote.</strong> ${t}</p>`;
const C=(where)=>foot(`[[work:cartan-1894|C.]], ${where}.`);
const common=m`\[\varpi=\sum_i m_i\bar\omega_i,\qquad \varpi=\sum_a p_a\Pi_a.\]`;
const orbitTable=type=>`<div class="source-table-wrap"><table class="source-weight-table"><caption>Author’s weight-orbit inventory · \\(${type[0]}_${type.slice(1)}\\)</caption><thead><tr><th scope="col">Group</th><th scope="col">Orbit representatives, including zero where listed</th></tr></thead><tbody>${exceptionalWeightOrbits[type].map((list,i)=>`<tr><th scope="row">\\(g_${i+1}\\)</th><td>\\(${list.map(orbitLabelLatex).join(',\\ ')}\\)</td></tr>`).join('')}</tbody></table></div>`;
const coordinateLatex=(row,d)=>row.map((v,i)=>{
 if(!v)return '';const sign=v<0?'-':'+',a=Math.abs(v),g=(x,y)=>y?g(y,x%y):x,k=g(a,d),num=a/k,den=d/k;
 const c=den===1?(num===1?'':String(num)):`\\frac{${num}}{${den}}`;
 return `${sign}${c}\\bar\\omega_{${i+1}}`;
}).join('').replace(/^\+/, '');
const fundamentalTable=(type,alternate)=>{const data=fundamentalWeightCoordinates[type];return `<div class="source-table-wrap"><table class="source-weight-table"><caption>Fundamental weights · \\(${type[0]}_${type.slice(1)}\\)</caption><thead><tr><th scope="col">Weight</th><th scope="col">Coordinate expression</th><th scope="col">Equivalent expression</th></tr></thead><tbody>${data.rows.map((row,i)=>`<tr><th scope="row">\\(\\Pi_${i+1}\\)</th><td>\\(${coordinateLatex(row,data.denominator)}\\)</td><td>\\(${alternate[i]}\\)</td></tr>`).join('')}</tbody></table></div>`;};
const rows=[
{n:1,part:1,p:56,title:'Remove the scalar dilations',type:'Invoked structural theorem',text:m`<p>Consider a homogeneous linear group in \(n\) variables \(x_1,\ldots,x_n\), preserving no linear subspace. I have previously proved that it is either simple or semisimple, or consists of a simple or semisimple subgroup together with the one-parameter group of dilations generated by</p>\[x_1\frac{\partial f}{\partial x_1}+\cdots+x_n\frac{\partial f}{\partial x_n}.\]<p>Thus determining the linear groups that preserve no linear subspace reduces to determining the simple and semisimple ones.</p>`+foot(m`<i>Simple infinite continuous transformation groups</i>, <i>Annales de l’École normale supérieure</i>, series 3, vol. XXVI, 1909, p. 99.`),note:m`<p>The variables and parameters remain complex, as stipulated at the end of the introduction. The relevant representation is finite-dimensional and irreducible. The infinitesimal image is semisimple, possibly with a scalar center; the scalar direction disappears projectively.</p><p>This structural result is cited rather than proved here. It concerns the connected continuous setting. It does not classify arbitrary disconnected irreducible matrix groups.</p>`},
{n:2,part:1,p:56,title:'Roots describe the infinitesimal algebra itself',type:'Definitions and two necessary exceptions',proof:'cartan13-proof-shift',text:m`<p>For a semisimple group of order \(r\) and rank \(l\), the infinitesimal transformations may be chosen as follows. There are \(l\) mutually commuting transformations \(Y_1,\ldots,Y_l\). The remaining \(r-l\) transformations \(X_1,\ldots,X_{r-l}\) satisfy</p>\[[Y_i,X_k]=m_{ik}X_k\qquad(1\le i\le l,\ 1\le k\le r-l),\]<p>with constant coefficients \(m_{ik}\). To each \(X_k\) corresponds a root \(\omega_k\) of the characteristic equation for \(e_1Y_1+\cdots+e_lY_l\). These roots are rational linear combinations of \(l\) independent ones, \(\omega_1,\ldots,\omega_l\), which may be chosen so that</p>\[\omega_\alpha=h_{\alpha1}\omega_1+\cdots+h_{\alpha l}\omega_l,\qquad h_{\alpha i}\in\mathbb Z.\]<p>The bracket of two transformations \(X_j,X_k\) is a nonzero multiple of the transformation belonging to \(\omega_j+\omega_k\), when that root exists; otherwise, the text says, it is zero. To each pair of roots \(\omega_\alpha,\omega_\beta\) is attached an integer \(a_{\alpha\beta}\): all the terms in the arithmetic progression of step \(\omega_\beta\) between \(\omega_\alpha\) and \(\omega_\alpha+a_{\alpha\beta}\omega_\beta\) are roots. There is also an integer \(a_{\beta\alpha}\), and in particular \(a_{\alpha\alpha}=-2\). Finally, the displayed expression for \(\omega_\alpha\) gives</p>\[a_{\alpha i}=h_{\alpha1}a_{1i}+\cdots+h_{\alpha l}a_{li}\qquad(1\le i\le r-l).\]`+C('Chapter IV, pp. 61–67'),note:m`<p>A [[concept:root-cartan-1913|root]] is the eigenvalue expression for the adjoint action on an infinitesimal direction. A weight below refers instead to a variable in a chosen linear representation.</p><p>The printed “otherwise zero” requires an exception: for opposite roots, \([X_\alpha,X_{-\alpha}]\) is a generally nonzero combination of the \(Y_i\), as Cartan himself uses in §6. Likewise the progression assertion requires care for parallel roots: \(0\) is not a root, although it lies between \(\alpha\) and \(-\alpha\). For nonparallel roots the stated segment property is valid.</p><p>With a positive-definite form on the real span of this finite root system, the sign convention is \(a_{\alpha\beta}=-2(\alpha,\beta)/(\beta,\beta)\). Linearity is in the first argument. It is not the convention of a modern Cartan matrix with positive diagonal entries.</p>`},
{n:3,part:1,p:57,title:'A weight, its reflection, and the chosen highest weight',type:'The author’s definitions',figure:'string',proof:'cartan13-proof-shift',text:m`<p>For a semisimple homogeneous linear group in \(n\) variables, the variables may be chosen so that each has a weight \(\varpi\). This weight is a rational linear combination of the fundamental roots:</p>\[\varpi=m_1\omega_1+\cdots+m_l\omega_l.\]<p>If \(x\) has weight \(\varpi\), then \(X_\alpha(x)\) is a linear combination of variables of weight \(\varpi+\omega_\alpha\). Put</p>\[b_\alpha=m_1a_{1\alpha}+\cdots+m_la_{l\alpha}.\]<p>Every weight in the arithmetic progression of step \(\omega_\alpha\) between \(\varpi\) and \(\varpi+b_\alpha\omega_\alpha\) occurs. Moreover, the numbers of variables of the two endpoint weights are equal. Write</p>\[S_\alpha\varpi=\varpi+b_\alpha\omega_\alpha.\]<p>This is the weight transformed by the substitution \(S_\alpha\). If \(\omega_{\alpha'}=-\omega_\alpha\), then \(S_{\alpha'}S_\alpha\varpi=\varpi\).</p><p>Call \(\varpi\) a [[concept:boundary-cartan-1913|boundary weight]] if no root \(\omega_\alpha\) has both \(\varpi+\omega_\alpha\) and \(\varpi-\omega_\alpha\) among the weights. Such weights exist: maximize the first coefficient \(m_1\); among these weights maximize \(m_2\), and continue. The resulting weight, called the <em>dominant weight</em>, is plainly a boundary weight.</p><p>If \(\varpi\) is a boundary weight, so is \(S_\alpha\varpi\). Otherwise some root \(\omega_\beta\) would give weights \(S_\alpha\varpi\pm\omega_\beta\), and applying \(S_{\alpha'}\) would give</p>\[\varpi\pm S_{\alpha'}\omega_\beta,\]<p>contrary to the hypothesis, since \(S_{\alpha'}\omega_\beta\) is itself a root. The same reasoning shows that a nonboundary weight remains nonboundary under \(S_\alpha\).</p>`+foot(m`[[work:cartan-1894|C.]], Chapter VIII, pp. 127–153. The weights \(\varpi\) are what I called “secondary roots” in my thesis.`),note:m`<p>The [[concept:weight-cartan-1913|weight space]] can have several independent variables; its dimension is its multiplicity. The [[concept:reflection-cartan-1913|substitution]] is a reflection of the finite weight system and preserves that multiplicity.</p><p>Cartan’s “dominant weight” here is the lexicographically highest weight of the representation, relative to the chosen ordering. Later, “a possible dominant weight” means a possible highest-weight label. Merely being maximal within one reflection orbit is weaker than being the highest weight of the entire representation.</p><p>The segment asserted here need not be a maximal root string. It runs between a weight and its reflected weight. The root-string reconstruction explains both the missing intermediate weights and the equality of endpoint multiplicities.</p>`},
{n:4,part:1,p:58,title:'Boundary weights form one orbit',type:'Original argument and proof qualification',figure:'a2',proof:'cartan13-proof-highest',text:m`<p>Call two weights <em>equivalent</em> when one is obtained from the other by a finite sequence of the transformations \(S_\alpha\). Thus the weights equivalent to \(\varpi\) have the form</p>\[S_{\alpha_n}\cdots S_{\alpha_1}\varpi.\]<p>They all have the same number of variables.</p><p>If the group preserves no linear subspace, all its boundary weights are equivalent to each other and to the dominant weight \(\Pi\). Suppose otherwise, and let \(\varpi_0\) be the highest boundary weight not equivalent to \(\Pi\). Consider the variables whose weights are \(\varpi_0\) or lower. I claim that the group transforms them among themselves.</p><p>Indeed, if applying \(X_\alpha\) to one of these variables produced a variable of weight higher than \(\varpi_0\), a progression in direction \(\omega_\alpha\) would contain a weight \(\varpi+\omega_\alpha\) higher than \(\varpi_0\). The argument asserts that there would then be a boundary weight \(\varpi+h\omega_\alpha\), with \(h\ge1\), necessarily equivalent to \(\varpi_0\). Reflecting it would give an equivalent weight \(\varpi-h'\omega_\alpha\), with \(h'\ge0\), lower than \(\varpi_0\), contrary to the hypothesis.</p><p>Since the group transforms the chosen variables among themselves, setting them all equal to zero gives an invariant linear subspace, again a contradiction. Hence any boundary weight determines all the others.</p>`,note:m`<p>The source calls these weights <i>homologues</i>. “Equivalent” here means exactly a [[concept:reflection-cartan-1913|reflection orbit]], with equal multiplicities. It is not equivalence of representations.</p><p>The printed proof compresses an important step: an endpoint in one root direction is not automatically a boundary weight in every root direction, and the asserted equivalence needs justification. We retain that step as the source’s argument. The linked reconstruction proves the conclusion using ordered root operators and the finite-dimensional three-generator relations, with its dependencies stated explicitly.</p>`},
{n:5,part:2,p:59,title:'Compare two cyclic constructions',type:'Fixed identification of infinitesimal structures',text:m`<p>We shall now prove that two irreducible linear groups of the same infinitesimal structure and the same dominant weight are similar.</p><p>In the first choose a variable \(u\) of dominant weight. Form all expressions</p>\[X_{\alpha_n}X_{\alpha_{n-1}}\cdots X_{\alpha_1}u,\tag{2}\]<p>where composition means successive application of the operators. List these infinitely many expressions as \(u_1,u_2,u_3,\ldots\). Each is a linear combination of variables of one weight. Starting from a variable \(v\) of dominant weight in the second group, form the corresponding expressions \(v_1,v_2,v_3,\ldots\). Corresponding expressions have the same weight. We may take \(u_1=u\) and \(v_1=v\).</p>`,note:m`<p>“Same structure” requires a fixed identification of the infinitesimal generators and their bracket constants. “Similar” means related by a linear change of variables intertwining their actions. It is stronger than having the same dimension.</p><p>The source speaks of isomorphic groups in the period’s infinitesimal sense. Its comparison does not settle which representations descend to a particular global quotient.</p>`},
{n:6,part:2,p:60,title:'Commute operators until a shorter word remains',type:'The original reduction argument',proof:'cartan13-proof-highest',text:m`<p>Among the expressions (2), consider one whose weight is again the dominant weight \(\varpi\). We shall show that it is \(ku\), where the number \(k\) depends only on the dominant weight and on the indices of the operators.</p><p>Write</p>\[\omega_{\alpha_i}=m_{i1}\omega_1+\cdots+m_{il}\omega_l.\]<p>The total change in weight is zero, so \(\sum_i\omega_{\alpha_i}=0\), and therefore \(\sum_i m_{ij}=0\) for every \(j\). If some first-coordinate coefficient is nonzero, one is positive. Choose the first such positive coefficient, at position \(h\).</p><p>If all preceding first-coordinate coefficients are zero, then the word is zero: otherwise its initial segment applied to \(u\) would have weight</p>\[\varpi'=\varpi+\omega_{\alpha_1}+\cdots+\omega_{\alpha_h},\]<p>whose first coefficient is greater than that of the dominant weight. In general, use the commutator identity</p>\[\begin{aligned}
X_{\alpha_n}\cdots X_{\alpha_h}X_{\alpha_{h-1}}\cdots X_{\alpha_1}u
={}&X_{\alpha_n}\cdots[X_{\alpha_h},X_{\alpha_{h-1}}]X_{\alpha_{h-2}}\cdots X_{\alpha_1}u\\
&+X_{\alpha_n}\cdots X_{\alpha_{h-1}}X_{\alpha_h}X_{\alpha_{h-2}}\cdots X_{\alpha_1}u.
\end{aligned}\]<p>In the first term the word length decreases by one. If the two roots sum to zero, the bracket is instead a combination of the \(Y_i\); acting on a weight vector, it supplies a scalar determined by its weight and the root, reducing the number of root operators by two. In the second term the length is unchanged but the selected positive-coefficient operator has moved one place to the right.</p><p>Continue moving it until no negative first-coordinate coefficient remains to its right; the surviving unreduced word is then zero. Repeat this shortening as long as a first-coordinate coefficient is nonzero. The reduction terminates, since a nonzero word of total weight zero cannot have just one root operator. Then apply the same argument to the second coefficients, and so on, until every root operator has disappeared. The original expression is therefore \(ku\), with \(k\) depending only on \(\varpi\) and the indices.</p>`+foot(m`This uses the theorem that \(Yu\) is a multiple of \(u\) when the weight of \(u\) is nonzero. It follows ultimately from the known properties of simple linear groups with three parameters. See also [[work:cartan-1894|C.]], pp. 99–102.`),note:m`<p>This is a reordering proof. A commutator replaces two root operators by one root operator, or by a diagonal operator for opposite roots. The diagonal operator acts by the value of the current weight.</p><p>Its constants are determined only after compatible normalizations of the root operators have been fixed. The written reconstruction packages this reduction with the ordered-monomial theorem; it does not assume that an arbitrary cyclic vector generates an irreducible module.</p>`},
{n:7,part:2,p:61,title:'The highest-weight space has dimension one',type:'Cyclicity and multiplicity',proof:'cartan13-proof-highest',text:m`<p>All the expressions \(u_1,u_2,\ldots\) are linear combinations of finitely many of them, at most as many as the variables of the group. Choose independent ones \(x_1,\ldots,x_p\), each of a definite weight. The subspace</p>\[x_1=\cdots=x_p=0\]<p>is invariant: each \(X_\alpha x_i\) is one of the expressions \(u_j\), hence a linear combination of the \(x_i\). Irreducibility therefore forces every variable of the group to be a linear combination of \(x_1,\ldots,x_p\).</p><p>The reduction just proved shows that only one independent expression among these has dominant weight. Consequently an irreducible linear group has exactly one variable of dominant weight, and hence exactly one variable of each boundary weight.</p>`,note:m`<p>A variable generates an invariant subspace of linear forms under successive operators. Its common zero set is the annihilator of that space in the original variable space. Irreducibility makes that span the whole dual representation.</p><p>“One variable” means multiplicity one, not a unique vector: nonzero scalar multiples remain possible. The same multiplicity at all boundary weights follows from reflection. Interior weights may have larger multiplicity, as the type-\(A_2\) drawing shows.</p>`},
{n:8,part:2,p:62,title:'The two constructions have the same relations',type:'The intertwiner constructed',proof:'cartan13-proof-highest',text:m`<p>We may choose</p>\[x_1=u_1,\quad x_2=u_{i_2},\quad\ldots,\quad x_p=u_{i_p},\qquad 1\lt i_2\lt \cdots\lt i_p.\]<p>Consider the successive relations expressing \(u_2,\ldots,u_{i_2-1}\) in terms of \(u_1\); then \(u_{i_2+1},\ldots,u_{i_3-1}\) in terms of \(u_1,u_{i_2}\); and so on. Transfer all these relations to the corresponding \(v_i\). Some might initially appear not to vanish. Each such remainder is a linear form of one weight in the second group. Let \(V_1,\ldots,V_q\) be independent remainders spanning them.</p><p>The group transforms the \(V_i\) among themselves: applying a root operator produces another relation whose counterpart in the \(u_i\) is identically zero. None of these remainders has dominant weight, because every word returning to that weight has the same scalar coefficient in the two groups, by the previous reduction. If \(q\ne0\), their common zero set would therefore be a proper invariant linear subspace of the second group, a contradiction.</p><p>Thus imposing the relations \(v_i=u_i\) creates no relation among either group’s original variables. Their actions agree: if \(X_\alpha u_i=u_j\), then \(X_\alpha v_i=v_j\). Hence the two groups are similar. The same conclusion holds if they have any boundary weight in common.</p>`,note:m`<p>The relations being compared are all linear dependencies among the operator words, not merely a finite initial sample. Stability follows by applying another generator to such a relation.</p><p>The linked proof supplies a concise rigorous version: the universal highest-weight construction has a unique simple quotient. Its use is restricted here to finite-dimensional complex representations of the fixed semisimple infinitesimal algebra.</p>`},
{n:9,part:2,p:63,proof:'cartan13-proof-multiplicity',title:'Recover weight positions, not their multiplicities',type:'The author’s finite procedure',text:m`<p>The proof also shows how to obtain all the weights once one boundary weight \(\varpi_0\) is known. First form its reflection orbit; this gives all the boundary weights. For every substitution with</p>\[S_\alpha\varpi_0=\varpi_0+h\omega_\alpha,\qquad h>1,\]<p>insert</p>\[\varpi_0+\omega_\alpha,\quad\ldots,\quad\varpi_0+\left\lfloor\frac h2\right\rfloor\omega_\alpha.\]<p>These are new, nonboundary weights. Form their reflection orbits. In each new orbit choose one representative and repeat the same operations, continuing until no new operation is possible. The result is a collection of reflection orbits. All weights in one orbit have the same number of variables.</p>`,note:m`<p>The set of weights is finite, so an implementation that records visited weights terminates. The half-string is enough because reflection supplies the other half.</p><p>This procedure describes support: which weights occur. It does not give their multiplicities. Neither an orbit size nor the number of listed weight expressions by itself gives the dimension of a general representation. The later exceptional-type inventories must be read with that distinction.</p>`},
{n:10,part:3,p:64,title:'The highest-weight component of a tensor product',type:'“Product” has a special meaning',proof:'cartan13-proof-product',text:m`<p>Consider two irreducible linear groups \(g_1,g_2\) isomorphic to each other, or more generally faithful or nonfaithful realizations of one semisimple group \(G\). Let their variables be \(x_1,\ldots,x_p\) and \(y_1,\ldots,y_q\). Choose fundamental roots of \(G\), and let \(\varpi,\varpi'\) be the two dominant weights. We may take \(x_1,y_1\) to be the unique variables of these weights.</p><p>The products \(x_i y_k\) transform linearly, giving a group in \(pq\) variables. Starting from \(x_1y_1\), apply the group’s transformations repeatedly. Choose independent combinations \(z_1,\ldots,z_s\) of these products, each of one weight, spanning the expressions obtained. The linear group on these \(s\) expressions preserves, the text asserts, no linear subspace. Call it the <em>product</em> of the two given groups. Its dominant weight is the sum of their dominant weights.</p><p>We have therefore constructed an irreducible linear group whose dominant weight is the sum of those of two given groups.</p>`,note:m`<p>The [[concept:cartan-product-1913|product]] here is the subrepresentation generated by the two highest variables’ product, often called the Cartan component. It is generally smaller than the full tensor product. The same group acts on both factors.</p><p>Cyclicity alone does not make a module irreducible. The proof below supplies this step using complete reducibility for complex semisimple infinitesimal algebras, together with the one-dimensional highest-weight space. “Faithful or nonfaithful” renders the source’s <i>holoédrique ou mériédrique</i>; it is not an assertion that all the global groups are isomorphic.</p>`},
{n:11,part:3,p:64,title:'The weight set adds, while multiplicities need not',type:'Repair of a compressed infinitesimal step',proof:'cartan13-proof-product',text:m`<p>We shall show that the weights of the product are all sums of a weight of the first factor and a weight of the second, without exception. Write the finite transformation of the first highest variable as</p>\[x'_1=a_1x_1+\cdots+a_px_p.\]<p>The coefficient functions \(a_i\) satisfy no constant linear relation. Otherwise a change of variables would make the last coefficients vanish identically, leaving a shorter independent list, and the group law would imply an invariant linear subspace. Similarly write</p>\[y'_1=b_1y_1+\cdots+b_qy_q.\]<p>Then</p>\[x'_1y'_1=\sum_{i,k}a_i b_k x_i y_k.\]<p>For every pair of indices, \(a_i b_k\) is not identically zero, since neither factor is. Except when both indices are the first, it is not constant either, since it vanishes at the identity. Thus it depends on the group parameters. Setting \(z_{ik}=x_i y_k\), the printed argument infers an infinitesimal transformation containing a term</p>\[(h z_{ik}+\cdots)\frac{\partial f}{\partial z_{11}}+\cdots.\]<p>It concludes that the product contains a variable with a nonzero \(z_{ik}\) coefficient, hence a weight equal to the sum of the weights of \(x_i\) and \(y_k\).</p><p>This theorem shows that the product does not depend on the initial choice of ordering used to define the dominant weight. Every boundary weight of the product is a sum of boundary weights of the factors.</p>`,note:m`<p>The coefficients are analytic functions on the same connected complex group, or on a common connected local parameter domain. Nonzero analytic functions have a nonzero product. This property is not true for arbitrary functions.</p><p>A nonconstant coefficient need not have a nonzero first derivative at the identity. Higher operator words may be necessary, so the printed infinitesimal inference is too quick. The reconstruction instead takes the span of the entire group orbit and projects onto a weight space. That proves the claimed support equality without making the first-derivative claim.</p><p>The last statement means that each boundary weight can be expressed using compatible boundary weights of the factors. It does not say that every pair of boundary weights has a boundary-weight sum.</p>`},
{n:12,part:4,p:66,title:'Unique nonnegative highest-weight labels',type:'Uniqueness first; existence still to come',proof:'cartan13-proof-labels',text:m`<p>For a simple structure of rank \(l\), we shall prove the existence of \(l\) particular irreducible linear groups from which every other such group is obtained as a product, allowing repeated factors. Equivalently, if their dominant weights are \(\Pi_1,\ldots,\Pi_l\), every possible dominant weight has the form</p>\[p_1\Pi_1+\cdots+p_l\Pi_l,\qquad p_i\in\mathbb Z_{\ge0}.\]<p>Call these the fundamental groups of the structure.</p><p>The system is unique, independently of the ordering used to choose a dominant weight. Indeed, the dominant weights, in the old ordering, of another fundamental system \(g'_i\) would be \(\sum_k p_{ik}\Pi_k\). Each old group \(g_i\) is in turn a product \(\prod_j(g'_j)^{q_{ij}}\). The product theorem therefore gives</p>\[\sum_{j,k}q_{ij}p_{jk}\Pi_k=\Pi_i.\]<p>This forces the two systems to agree. The only doubtful case would be a fundamental weight expressible as a nonnegative integral combination of the others; then the labels would not be unique. We shall see separately in each simple type that this does not occur.</p><p>Once the simple cases are determined, a semisimple structure is handled by taking the fundamental groups of its simple factors and all their products. Their total number is again the rank \(l\); as realizations of the whole semisimple structure, they are nonfaithful in general.</p><p>We now examine the simple types. First we determine their possible fundamental dominant weights; afterward we shall construct linear groups realizing them.</p>`,note:m`<p>“Product” keeps the meaning of §10. For different simple factors it becomes the usual irreducible tensor action; for repeated factors of one structure it is the highest-weight component.</p><p>The coefficient formulas below show linear independence and unique nonnegative integer coordinates. That supplies the missing hypothesis in the uniqueness argument. They determine allowable labels; existence of the corresponding representations is deferred to Sections XIV–XXII, which are not yet rendered here.</p><p>The all-zero label gives the trivial representation. For a semisimple algebra, a label can vanish on an entire simple factor and hence give a nonfaithful realization. These cases explain the source’s qualification at the end.</p>`}
];
rows.push(
{n:13,part:5,p:67,title:'Type A: sort the coordinates',type:'The coordinate convention changes here',text:m`<p>The roots are</p>\[\bar\omega_i-\bar\omega_j\quad(i\ne j;\ 1\le i,j\le l+1),\qquad \bar\omega_1+\cdots+\bar\omega_{l+1}=0.\]<p>Every weight can be written \(\varpi=\sum_{i=1}^{l+1}m_i\bar\omega_i\), with the normalization \(\sum_i m_i=0\). For the root \(\bar\omega_i-\bar\omega_j\), the reflection coefficient is \(b=-m_i+m_j\). Thus the differences \(m_i-m_j\) are integers, and the coefficients have denominators dividing \(l+1\).</p><p>Define the highest weight by successively maximizing \(m_1,m_2,\ldots\). A weight is highest among its equivalent weights precisely when</p>\[m_1\ge m_2\ge\cdots\ge m_{l+1}.\]`,note:m`<p>The barred coordinate quantities are not all roots themselves. Their pairwise differences are the roots. The normalization removes the freedom to add a common constant to every coefficient.</p><p>Here reflection simply permutes two coordinates. Sorting therefore gives the lexicographically highest point in an orbit. Integrality of the reflection coefficient, rather than the bare fact that a permutation is possible, gives the lattice restriction.</p>`},
{n:14,part:5,p:68,title:'Type A: the fundamental labels and the exterior-coordinate count',type:'A printed fraction corrected explicitly',proof:'cartan13-proof-labels',text:m`<p>Among possible dominant weights choose</p>\[\begin{aligned}
\Pi_1&=-\bar\omega_{l+1},\\
\Pi_2&=-\bar\omega_l-\bar\omega_{l+1},\\
\Pi_i&=-\sum_{a=l+2-i}^{l+1}\bar\omega_a
=\frac{i\sum_{a=1}^{l+1-i}\bar\omega_a-(l+1-i)\sum_{a=l+2-i}^{l+1}\bar\omega_a}{l+1},\\
\Pi_l&=\bar\omega_1.
\end{aligned}\]<p>The unsimplified fractions in the print contain coefficient and index errors; the displayed general fraction here has been corrected to agree with its right-hand expression. Every dominant weight is \(\varpi=\sum_i p_i\Pi_i\), where</p>\[p_1=m_l-m_{l+1},\quad p_2=m_{l-1}-m_l,\quad\ldots,\quad p_l=m_1-m_2.\]<p>The weights of each \(g_i\) are all equivalent. They are obtained by every permutation of the coordinate indices in \(\Pi_i\). Consequently, assuming the group exists, it has \(\binom{l+1}{i}\) variables.</p>`,note:m`<p>On p. 68 the fraction printed for \(\Pi_2\) uses \(-(l-2)\) for the last two coefficients; it must use \(-(l-1)\). The printed general fraction also has inconsistent ranges. The simple expressions \(-\bar\omega_{l+1},-\bar\omega_l-\bar\omega_{l+1},\ldots\) fix the intended weights unambiguously.</p><p>This is Cartan’s indexing, reversed relative to a common modern ordering of the type-\(A_l\) fundamental weights. There are \(\binom{l+1}{i}\) distinct permutations, and each is a boundary weight of multiplicity one. Only with that multiplicity fact is this a dimension count.</p>`},
{n:15,part:6,p:69,title:'Type B: integers or simultaneous half-integers',type:'Reflections and the weight lattice',text:m`<p>The roots are</p>\[\pm\bar\omega_i,\qquad \pm\bar\omega_i\pm\bar\omega_j\quad(i\ne j;\ 1\le i,j\le l).\]<p>Write \(\varpi=\sum_i m_i\bar\omega_i\). Denote the reflections belonging to \(\bar\omega_i\), \(\bar\omega_i+\bar\omega_j\), \(\bar\omega_i-\bar\omega_j\) by \(S_i,S_{ij},S'_{ij}\). Then</p>\[\begin{aligned}
S_i\varpi&=\varpi-2m_i\bar\omega_i,\\
S_{ij}\varpi&=\varpi-(m_i+m_j)(\bar\omega_i+\bar\omega_j),\\
S'_{ij}\varpi&=\varpi-(m_i-m_j)(\bar\omega_i-\bar\omega_j).
\end{aligned}\]<p>Thus the \(m_i\) are either all integers or all half-integers with odd numerators. In the same ordering as before, the condition for a highest orbit representative is exactly</p>\[m_1\ge m_2\ge\cdots\ge m_l\ge0.\]`+C('p. 79'),note:m`<p>These reflections allow every sign change and every permutation. Taking absolute values and sorting proves the chamber condition. The reflection coefficients require \(2m_i\in\mathbb Z\) and \(m_i\pm m_j\in\mathbb Z\), giving the two permitted lattice cosets.</p><p>The half-integer coset is essential for the spin representation. Restricting silently to integer coordinates would remove one of the fundamental representations being classified.</p>`},
{n:16,part:6,p:69,title:'Type B: the spin weight comes first',type:'The author’s support inventory',figure:'b2',text:m`<p>Choose the fundamental weights</p>\[\Pi_1=\frac{\bar\omega_1+\cdots+\bar\omega_l}{2},\qquad
\Pi_a=\bar\omega_1+\cdots+\bar\omega_{a-1}\quad(2\le a\le l).\]<p>Every dominant weight is their nonnegative integer combination, with</p>\[p_1=2m_l,\qquad p_a=m_{a-1}-m_a\quad(2\le a\le l).\]<p>The weights of \(g_1\) are</p>\[\frac{\pm\bar\omega_1\pm\bar\omega_2\pm\cdots\pm\bar\omega_l}{2};\]<p>there are \(2^l\), all boundary weights. Those of \(g_2\) are \(\pm\bar\omega_i\) and \(0\), the first \(2l\) being boundary weights. Those of \(g_3\) are \(\pm\bar\omega_i\pm\bar\omega_j\) together with the weights of \(g_2\); the new weights are boundary weights. In general, the support of \(g_a\) consists of</p>\[\pm\bar\omega_{i_1}\pm\cdots\pm\bar\omega_{i_{a-1}}\]<p>with distinct indices, together with the weights of \(g_{a-1}\). The first weights are boundary weights.</p>`,note:m`<p>The uniform lists concern the simple type \(B_l\) in rank \(l\ge2\); a displayed \(g_a\) is used only when \(a\le l\). The signs vary independently, and indices within a sum are distinct.</p><p>The support of a non-spin fundamental representation includes lower layers. Their multiplicities are not supplied by this inventory. The rank-two drawing distinguishes the four spin weights from the five weights of the vector representation.</p>`},
{n:17,part:7,p:70,title:'Type C: the same reflection group, a different lattice',type:'Root lengths affect integrality',text:m`<p>The roots are</p>\[\pm2\bar\omega_i,\qquad\pm\bar\omega_i\pm\bar\omega_j\quad(i\ne j;\ 1\le i,j\le l).\]<p>For \(\varpi=\sum_i m_i\bar\omega_i\), let \(S_{ii},S_{ij},S'_{ij}\) denote the reflections for \(2\bar\omega_i\), \(\bar\omega_i+\bar\omega_j\), \(\bar\omega_i-\bar\omega_j\). Their actions are</p>\[\begin{aligned}
S_{ii}\varpi&=\varpi-2m_i\bar\omega_i,\\
S_{ij}\varpi&=\varpi-(m_i+m_j)(\bar\omega_i+\bar\omega_j),\\
S'_{ij}\varpi&=\varpi-(m_i-m_j)(\bar\omega_i-\bar\omega_j).
\end{aligned}\]<p>The \(m_i\) are integers. The necessary and sufficient highest-orbit condition is again</p>\[m_1\ge m_2\ge\cdots\ge m_l\ge0.\]`+C('p. 79'),note:m`<p>The transformations of the coordinate tuples look the same as in type \(B\), but the root \(2\bar\omega_i\) has reflection coefficient \(-m_i\), not \(-2m_i\). Its integrality excludes the half-integer lattice coset.</p><p>This is why the reflection action alone does not determine the allowed representation labels: the root normalization is part of the data.</p>`},
{n:18,part:7,p:70,title:'Type C: successively longer coordinate sums',type:'Support layers have the same parity',text:m`<p>Choose</p>\[\Pi_a=\bar\omega_1+\cdots+\bar\omega_a\qquad(1\le a\le l).\]<p>Every dominant weight is their nonnegative integer combination, with</p>\[p_a=m_a-m_{a+1}\quad(1\le a\lt l),\qquad p_l=m_l.\]<p>These weights are therefore fundamental. The weights of \(g_1\) are the \(2l\) boundary weights \(\pm\bar\omega_i\). Those of \(g_2\) are \(\pm\bar\omega_i\pm\bar\omega_j\) and \(0\), all boundary except zero. Those of \(g_3\) are \(\pm\bar\omega_i\pm\bar\omega_j\pm\bar\omega_k\) and the weights of \(g_1\), the first being boundary weights; and so on.</p>`,note:m`<p>The recurrence drops the number of nonzero coordinates by two: for \(g_a\), the boundary layer has \(a\) signed distinct coordinates, and the lower layers have \(a-2,a-4,\ldots\). It does not include every lower fundamental support indiscriminately.</p><p>The coefficients telescope, proving the displayed expansion and uniqueness. The later construction of the groups remains a separate existence step.</p>`},
{n:19,part:8,p:71,title:'Type D: only an even number of sign changes',type:'The last coordinate may remain negative',text:m`<p>The roots are</p>\[\pm\bar\omega_i\pm\bar\omega_j\qquad(i\ne j;\ 1\le i,j\le l).\]<p>For \(\varpi=\sum_i m_i\bar\omega_i\), the two corresponding reflections are</p>\[\begin{aligned}
S_{ij}\varpi&=\varpi-(m_i+m_j)(\bar\omega_i+\bar\omega_j),\\
S'_{ij}\varpi&=\varpi-(m_i-m_j)(\bar\omega_i-\bar\omega_j).
\end{aligned}\]<p>The coefficients are either all integers or all half-integers with odd numerators. For \(i\lt j\), dominance requires \(m_i\ge m_j\) and \(m_i\ge-m_j\). Equivalently, the necessary and sufficient conditions are</p>\[m_1\ge m_2\ge\cdots\ge m_{l-1}\ge |m_l|.\]`+C('p. 79'),note:m`<p>Here permutations and even sign changes are possible. One cannot always make the last coordinate positive. Dropping the absolute value condition or forcing \(m_l\ge0\) would merge or discard the two half-spin labels.</p><p>The uniform simple type is \(D_l\) for \(l\ge4\). The lower-rank coincidences do not create extra fundamental groups in this list.</p>`},
{n:20,part:8,p:72,title:'Type D: the two half-spin weights',type:'Fundamental labels with Cartan’s indexing',text:m`<p>Choose</p>\[\begin{aligned}
\Pi_1&=\tfrac12(\bar\omega_1+\cdots+\bar\omega_{l-1}-\bar\omega_l),\\
\Pi_2&=\tfrac12(\bar\omega_1+\cdots+\bar\omega_{l-1}+\bar\omega_l),\\
\Pi_a&=\bar\omega_1+\cdots+\bar\omega_{a-2}\quad(3\le a\le l).
\end{aligned}\]<p>Every dominant weight is their nonnegative integer combination, with</p>\[p_1=m_{l-1}-m_l,\quad p_2=m_{l-1}+m_l,\quad p_a=m_{a-2}-m_{a-1}\ (3\le a\le l).\]<p>The weights of \(g_1\) and \(g_2\) are all boundary weights, \(2^{l-1}\) in each. The weights of \(g_3\) are \(\pm\bar\omega_i\), all boundary. Those of \(g_4\) are \(\pm\bar\omega_i\pm\bar\omega_j\) and zero, all boundary except zero. Those of \(g_5\) are the signed sums on three distinct indices together with the weights of \(g_3\); and so on.</p>`,note:m`<p>Each half-spin orbit consists of half of the \(2^l\) sign patterns: one parity of the number of minus signs. The two orbits remain distinct under even sign changes.</p><p>As in type \(C\), the non-spin supports have layers dropping by two signed coordinates. All boundary multiplicities are one; this passage still does not specify the multiplicities of the lower layers.</p>`}
);
rows.push(
{n:21,part:9,p:72,title:'Type E, rank six: roots and reflection coefficients',type:'A lattice assertion in the print needs correction',text:m`<p>The roots are</p>\[\begin{aligned}
\omega_{ij}&=\bar\omega_i-\bar\omega_j,\\
\omega_{ijk}&=\bar\omega_i+\bar\omega_j+\bar\omega_k,\qquad \omega'_{ijk}=-\omega_{ijk},\\
\omega_{000}&=3\bar\omega_0=-\sum_{a=1}^{6}\bar\omega_a,\qquad \omega'_{000}=-3\bar\omega_0.
\end{aligned}\]<p>Indices in a pair or triple are distinct and range from one to six. For \(\varpi=\sum_{i=1}^{6}m_i\bar\omega_i\), set \(T=\tfrac13\sum_i m_i\) to shorten the formulas. The reflections are</p>\[\begin{aligned}
S_{ij}\varpi&=\varpi-(m_i-m_j)(\bar\omega_i-\bar\omega_j),\\
S_{ijk}\varpi&=\varpi+(T-m_i-m_j-m_k)(\bar\omega_i+\bar\omega_j+\bar\omega_k),\\
S_{000}\varpi&=\varpi-T\sum_{a=1}^{6}\bar\omega_a.
\end{aligned}\]<p>The printed text infers that the \(m_i\) have integral differences, that their sum is a multiple of three, and that the sum of any three is a multiple of three. This last statement is erroneous as printed; see the correction beside the passage. In particular, their common fractional part is zero, one third, or two thirds.</p><p>For a highest orbit representative,</p>\[m_1\ge m_2\ge\cdots\ge m_6,\qquad T-m_4-m_5-m_6\le0.\]<p>The latter condition is equivalent to</p>\[m_1+m_2+m_3\le2(m_4+m_5+m_6).\]`+C('pp. 80 and 142'),note:m`<p>The reflection coefficients must be integers. The precise requirements are \(m_i-m_j\in\mathbb Z\), \(T\in\mathbb Z\), and \(T-m_i-m_j-m_k\in\mathbb Z\). Consequently triple sums are integers, but need not be multiples of three.</p><p>For example, \(\Pi_1\) in §23 has its first three coefficients equal to \(2/3\), whose sum is \(2\). It contradicts the printed multiple-of-three assertion while satisfying the reflection conditions.</p><p>The coordinate vectors are not orthonormal. A compatible inner product is \((\bar\omega_i,\bar\omega_j)=\delta_{ij}-1/9\); it makes these roots have squared length \(2\) and reproduces all three reflection formulas.</p>`},
{n:22,part:9,p:73,title:'Type E, rank six: the orbit patterns and the chamber',type:'The complete coefficient table',text:m`<p>Conversely, suppose</p>\[m_1\ge\cdots\ge m_6,\qquad m_4+m_5+m_6\ge T.\tag{E6}\]<p>No equivalent weight is higher. Apart from the starting tuple and coordinate permutations, the coefficient patterns used in the argument are the following; \(i,j,k,r,s,t\) denote all six indices in any order:</p>\[\begin{array}{ll}
1.&(m_1-T,m_2-T,m_3-T,m_4-T,m_5-T,m_6-T),\\[3pt]
2.&(m_i,m_j,m_k,T-m_s-m_t,T-m_t-m_r,T-m_r-m_s),\\[3pt]
3.&(m_i-T,m_j-T,m_k-T,T-m_s-m_t,T-m_t-m_r,T-m_r-m_s),\\[3pt]
4.&(m_i,m_i-T,T-m_j-m_k,T-m_j-m_r,T-m_j-m_s,T-m_j-m_t).
\end{array}\]<p>If one of these were at least as high as the original tuple, one of the following inequalities would hold:</p>\[m_1-T\ge m_1,\qquad T-m_5-m_6\ge m_1.\]<p>The first gives \(\sum_i m_i\le0\). Together with (E6), this gives</p>\[m_1+m_2+m_3-(m_4+m_5+m_6)\le0,\]<p>which, by the ordering, forces every coefficient to vanish. The second gives</p>\[T\le m_4+m_5+m_6\le m_1+m_5+m_6\le T.\]<p>Hence</p>\[m_1=m_2=m_3=m_4=2(m_5+m_6).\]<p>Put these four coefficients equal to \(2a\), and put \(m_5=b\), \(m_6=a-b\), with \(2a\ge b\ge a/2\ge0\). Direct checking in this remaining case again shows that no equivalent weight is higher. Thus (E6) completely characterizes the dominant orbit representatives.</p>`+foot(m`The letters \(i,j,k,r,s,t\) designate the six indices in any order.`),note:m`<p>The shorthand \(T\) is editorial and means one third of the sum of the current starting coefficients. The original tuple must also be included when enumerating an orbit. Permutations of the output coefficients, as well as choices of indices in a pattern, are allowed.</p><p>The point is a chamber test inside the real span of this particular finite root system. The weight is still a label for a complex representation. The linked reconstruction below verifies the chamber and coefficient claims through the simple-root pairings rather than treating “direct checking” as a proof for all representations.</p>`},
{n:23,part:9,p:75,title:'Type E, rank six: six fundamental weights',type:'The fundamental-coordinate inversion',proof:'cartan13-proof-labels',text:m`<p>The following dominant weights are readily obtained, in the displayed order:</p>`+fundamentalTable('E6',[m`-\bar\omega_6-2\bar\omega_0`,m`-3\bar\omega_0`,m`\bar\omega_1-\bar\omega_0`,m`-\bar\omega_5-\bar\omega_6-4\bar\omega_0`,m`\bar\omega_1+\bar\omega_2-2\bar\omega_0`,m`\bar\omega_1+\bar\omega_2+\bar\omega_3-3\bar\omega_0`])+m`<p>They are fundamental, since every dominant weight is their nonnegative integer combination. Its coefficients are</p>\[\begin{aligned}
p_1&=m_5-m_6,\\
p_2&=\tfrac23(m_4+m_5+m_6)-\tfrac13(m_1+m_2+m_3),\\
p_3&=m_1-m_2,\qquad p_4=m_4-m_5,\\
p_5&=m_2-m_3,\qquad p_6=m_3-m_4.
\end{aligned}\]`,note:m`<p>Substituting each listed \(\Pi_j\) into these six formulas gives \(p_i=\delta_{ij}\). This proves their linear independence and reconstructs every coefficient tuple. The chamber inequalities give nonnegativity; the reflection-integrality conditions give integrality.</p><p>The enumeration is Cartan’s own, rather than a silent substitution of a later standard numbering. Some of the listed fundamental weights are higher than preceding entries in literal lexicographic order; the phrase “in order of height” in the source should not be used as a sorting rule for these tables.</p>`},
{n:24,part:9,p:75,proof:'cartan13-proof-labels',title:'Type E, rank six: the full support inventory',type:'Distinct indices and boundary layers',text:m`<p>The weights of \(g_1\) are</p>\[-\bar\omega_i+\bar\omega_0,\quad-\bar\omega_i-2\bar\omega_0,\quad\bar\omega_i+\bar\omega_j+\bar\omega_0,\]<p>all boundary. Those of \(g_2\) are</p>\[\bar\omega_i-\bar\omega_j,\quad\pm(\bar\omega_i+\bar\omega_j+\bar\omega_k),\quad\pm3\bar\omega_0,\]<p>all boundary except zero. Those of \(g_3\) are</p>\[\bar\omega_i-\bar\omega_0,\quad\bar\omega_i+2\bar\omega_0,\quad-\bar\omega_i-\bar\omega_j-\bar\omega_0,\]<p>all boundary. Those of \(g_4\) are the weights of \(g_3\) and these further boundary weights:</p>\[\begin{gathered}
-2\bar\omega_i-\bar\omega_0,\quad-\bar\omega_i-\bar\omega_j+2\bar\omega_0,\quad-\bar\omega_i-\bar\omega_j-4\bar\omega_0,\\
-\bar\omega_i+\bar\omega_j+\bar\omega_k-\bar\omega_0,\quad
-\bar\omega_i+\bar\omega_j+\bar\omega_k+2\bar\omega_0,\\
2\bar\omega_i+\bar\omega_j+\bar\omega_k+2\bar\omega_0.
\end{gathered}\]<p>The weights of \(g_5\) are those of \(g_1\) together with the negatives of the boundary weights of \(g_4\). Finally, the weights of \(g_6\) consist of those of \(g_2\), then the boundary weights of the product \(g_1g_3\),</p>\[\begin{gathered}
\pm(2\bar\omega_i+\bar\omega_j),\quad\bar\omega_i+\bar\omega_j-\bar\omega_k-\bar\omega_l,\\
\pm(\bar\omega_i+\bar\omega_j+\bar\omega_k+\bar\omega_l-\bar\omega_m),\quad
\pm(\bar\omega_i-\bar\omega_j-3\bar\omega_0),
\end{gathered}\]<p>and then the boundary weights of \(g_6\),</p>\[\begin{gathered}
\pm(\bar\omega_i+\bar\omega_j-2\bar\omega_k),\quad
\pm(2\bar\omega_i+2\bar\omega_j+\bar\omega_k+\bar\omega_l),\\
\pm(2\bar\omega_i+2\bar\omega_j+\bar\omega_k-\bar\omega_l),\quad
\pm(\bar\omega_i+\bar\omega_j+\bar\omega_k-3\bar\omega_0).
\end{gathered}\]<p>The third family is retained as printed here; its correction and an omitted boundary layer are given in the commentary.</p>`,note:m`<p>Indices appearing in one sum are distinct, except where a repeated contribution is indicated by a coefficient. In the \(g_2\) list zero is obtained by taking equal indices in the difference; equivalently, add zero separately to the root list.</p><p>The intermediate displayed families form the boundary orbit of the product \(g_1g_3\), whose highest weight is \(\Pi_1+\Pi_3\). That orbit has \(270\) distinct weights. It is different from the final boundary orbit, that of \(g_6\) itself.</p><p>The printed family \(\pm(2\bar\omega_i+2\bar\omega_j+\bar\omega_k-\bar\omega_l)\) has squared norm \(74/9\), while \(\Pi_6\) has norm \(6\). It cannot belong to its reflection orbit. Replacing the second coefficient \(2\) by \(1\) repairs that family. Even then the displayed list has only \(700\) of the \(720\) boundary weights. The missing \(20\) are</p>\[2(\bar\omega_i+\bar\omega_j+\bar\omega_k)+3\bar\omega_0\qquad(i,j,k\text{ distinct}).\]<p>These are editorial repairs, checked by exact integer reflections. Together the repaired families and the additional layer are exactly the orbit of \(\Pi_6\). The reconstruction gives the reproducible finite check. This repairs the boundary list; it does not supply the multiplicities of the interior weights.</p>`}
);
rows.push(
{n:25,part:10,p:76,title:'Type E, rank seven: the lattice and chamber',type:'A second exceptional coordinate model',text:m`<p>The roots are</p>\[\begin{aligned}
\omega_{ij}&=\bar\omega_i-\bar\omega_j,\\
\omega_{ijk}&=\bar\omega_i+\bar\omega_j+\bar\omega_k,\qquad \omega'_{ijk}=-\omega_{ijk},\\
\omega_{00i}&=2\bar\omega_0+\bar\omega_i,\qquad \omega'_{00i}=-\omega_{00i},
\end{aligned}\]<p>with indices from one to seven, distinct within each pair or triple, and</p>\[2\bar\omega_0+\bar\omega_1+\cdots+\bar\omega_7=0.\]<p>Write \(\varpi=\sum_{i=1}^{7}m_i\bar\omega_i\) and again abbreviate \(T=\tfrac13\sum_i m_i\). Then</p>\[\begin{aligned}
S_{ij}\varpi&=\varpi-(m_i-m_j)(\bar\omega_i-\bar\omega_j),\\
S_{ijk}\varpi&=\varpi+(T-m_i-m_j-m_k)(\bar\omega_i+\bar\omega_j+\bar\omega_k),\\
S_{00i}\varpi&=\varpi+(T-m_i)(2\bar\omega_0+\bar\omega_i).
\end{aligned}\]<p>The numbers \(m_i-m_j\) and \(m_i+m_j\) are integers. Hence either every \(m_i\) is an integer and their sum is a multiple of three, or every \(m_i\) is a half-integer with odd numerator and the sum of the numerators is a multiple of three. The dominance conditions are</p>\[m_1\ge\cdots\ge m_7,\qquad m_1\le T\le m_5+m_6+m_7.\tag{E7}\]<p>They also imply that \(m_6\) is nonnegative.</p>`+C('pp. 80 and 143'),note:m`<p>The interval in (E7) has the direction printed in the scan: \(m_1\le T\). Raw OCR can reverse it. The inner product \(\delta_{ij}-1/9\), now on seven independent coordinates, again reproduces the reflections.</p><p>The parity and divisibility conditions are part of the weight lattice, not an optional simplification. For example, the half-integer fundamental weights below cannot be dropped.</p>`},
{n:26,part:10,p:77,title:'Type E, rank seven: the complete orbit-pattern table',type:'One fraction in the table is corrected',text:m`<p>Apart from coordinate order, the equivalent coefficient patterns used in the argument are</p>\[\begin{array}{ll}
1.&(m_i,m_j,m_k,m_l,T-m_s-m_t,T-m_t-m_r,T-m_r-m_s),\\[3pt]
2.&(m_i,m_i+m_j-T,m_i+m_k-T,m_i+m_l-T,\\
&\hspace{14mm}m_i+m_r-T,m_i+m_s-T,m_i+m_t-T),\\[3pt]
3.&(m_i,m_j,m_i+m_j-T,T-m_k-m_l,T-m_k-m_r,\\
&\hspace{14mm}T-m_k-m_s,T-m_k-m_t),\\[3pt]
4.&(m_i,m_i+m_j-T,m_i+m_k-T,m_i+m_l-T,\\
&\hspace{14mm}T-m_s-m_t,T-m_t-m_r,T-m_r-m_s).
\end{array}\]<p>Here the seven indices run through all their values in any order. Include also the patterns obtained by changing all signs, and the starting tuple. In the third row the print has one half of the total sum in place of \(T\); this has been corrected to one third.</p><p>Assume (E7). If an equivalent weight were higher, one of these inequalities would hold:</p>\[-m_7\ge m_1,\qquad T-m_i-m_j\ge m_k,\qquad m_1+m_2-T\ge m_3.\]<p>The first yields</p>\[m_6+m_7\le m_1+m_7\le0,\qquad m_1\le T\le m_5+m_6+m_7\le m_5.\]<p>Thus \(m_1=\cdots=m_5\), \(m_6+m_7=0\), and then \(3m_1=5m_1=0\), so also \(m_6=m_7=0\). The second inequality gives</p>\[m_i+m_j+m_k\le T\le m_5+m_6+m_7\le m_i+m_j+m_k,\]<p>so the supposed inequality is only equality. The last forces</p>\[m_1=m_2=2a,\qquad m_3=m_4=m_5=m_6=m_7=a.\]<p>A direct check again shows that the starting weight is at least as high as every equivalent one. Therefore the conditions (E7) are necessary and sufficient.</p>`,note:m`<p>The source’s third-row coefficient \(m_i+m_j-\tfrac12\sum m_a\) is inconsistent with its other reflections. It must be \(m_i+m_j-\tfrac13\sum m_a\). For example, on \(m=(1,1,1,1,1,1,0)\), one printed pattern changes the squared norm from \(2\) to \(32/9\); a reflection cannot do that.</p><p>The corrected patterns preserve the same inner product as the root reflections. The exceptional rows are retained in full, rather than replacing the computation with a table of modern dimensions.</p>`},
{n:27,part:10,p:79,title:'Type E, rank seven: seven fundamental labels',type:'An erroneous alternative expression is disclosed',proof:'cartan13-proof-labels',text:m`<p>The following are the fundamental dominant weights:</p>`+fundamentalTable('E7',[m`-\bar\omega_7-2\bar\omega_0`,m`\bar\omega_1-\bar\omega_0`,m`-3\bar\omega_0`,m`\bar\omega_1+\bar\omega_2-2\bar\omega_0`,m`-\bar\omega_6-\bar\omega_7-4\bar\omega_0`,m`\bar\omega_1+\bar\omega_2+\bar\omega_3-3\bar\omega_0`,m`-6\bar\omega_0-\bar\omega_5-\bar\omega_6-\bar\omega_7`])+m`<p>The last alternative expression has been corrected; the expanded coordinate expression agrees with the print. Every dominant weight is their nonnegative integer combination, with</p>\[\begin{aligned}
p_1&=m_6-m_7,&p_2&=m_1-m_2,\\
p_3&=m_5+m_6+m_7-T,&p_4&=m_2-m_3,\\
p_5&=m_5-m_6,&p_6&=m_3-m_4,\\
p_7&=m_4-m_5.
\end{aligned}\]`,note:m`<p>The print gives the alternative expression \(2\bar\omega_5+2\bar\omega_6+2\bar\omega_7-2\bar\omega_0\) for \(\Pi_7\). It does not equal its expanded coordinate expression. Eliminating \(\bar\omega_0\) gives the corrected alternative shown here.</p><p>Testing the seven label formulas on the seven expanded weights gives the identity matrix. That both checks the correction and proves uniqueness of the labels; it does not yet construct the representations.</p>`},
{n:28,part:10,p:79,title:'Type E, rank seven: all the listed weight orbits',type:'The support inventory',text:m`<p>The weights of \(g_1\) are zero and the boundary weights equivalent to \(\Pi_1\), namely</p>\[\bar\omega_i-\bar\omega_j,\qquad\pm(\bar\omega_i+\bar\omega_j+\bar\omega_k),\qquad\pm(2\bar\omega_0+\bar\omega_i).\]<p>The weights of \(g_2\) are the boundary weights equivalent to \(\Pi_2\):</p>\[\pm(\bar\omega_i-\bar\omega_0),\qquad\pm(\bar\omega_0+\bar\omega_i+\bar\omega_j).\]<p>The complete remaining orbit inventory, together with these first two cases, is as follows. Each nonzero entry means all weights equivalent to that representative; the orbit of \(\Pi_a\) is the boundary orbit for \(g_a\).</p>`+orbitTable('E7'),note:m`<p>The table is a compact rendering of every list in §28, including the continuation on p. 80. A sum such as \(\Pi_1+\Pi_2\) names one reflection orbit; it is not an instruction to add all pairs of weights independently.</p><p>The source lists positions and uses the earlier procedure; it does not give multiplicities here. Zero must be counted with its actual weight-space dimension when a representation dimension is wanted.</p>`},
{n:29,part:11,p:80,title:'Type E, rank eight: nine dependent coordinates',type:'Normalization and roots',text:m`<p>The roots are</p>\[\omega_{ij}=\bar\omega_i-\bar\omega_j,\qquad
\omega_{ijk}=\bar\omega_i+\bar\omega_j+\bar\omega_k,\qquad\omega'_{ijk}=-\omega_{ijk},\]<p>on distinct indices from one to nine, with \(\sum_{i=1}^{9}\bar\omega_i=0\). Every weight has a representative</p>\[\varpi=\sum_{i=1}^{9}m_i\bar\omega_i,\qquad \sum_i m_i=0.\]<p>The reflections are</p>\[\begin{aligned}
S_{ij}\varpi&=\varpi-(m_i-m_j)(\bar\omega_i-\bar\omega_j),\\
S_{ijk}\varpi&=\varpi-(m_i+m_j+m_k)(\bar\omega_i+\bar\omega_j+\bar\omega_k)\\
&\hspace{8mm}+\tfrac13(m_i+m_j+m_k)\sum_{a=1}^{9}\bar\omega_a.
\end{aligned}\]<p>The coefficients have integral differences; they have denominators dividing three, with numerators congruent modulo three. The necessary highest-orbit conditions are</p>\[m_1\ge\cdots\ge m_9,\qquad m_1+m_8+m_9\ge0\ge m_2+m_3+m_4.\]<p>As in the two preceding cases, these inequalities are also sufficient.</p>`+C('p. 80'),note:m`<p>The last term is zero as a vector but matters for the coefficient tuple: it restores the sum-zero normalization after the reflection. Omitting it in coordinate calculations gives wrong subsequent formulas.</p><p>The nine-coordinate inner product \(\delta_{ij}-1/9\) has a one-dimensional null direction. On the sum-zero subspace it is positive definite. This is an eight-dimensional weight model, not a representation on nine variables.</p>`},
{n:30,part:11,p:81,title:'Type E, rank eight: eight fundamental labels',type:'The exact coefficient inversion',proof:'cartan13-proof-labels',text:m`<p>Choose the following eight dominant weights:</p>`+fundamentalTable('E8',[m`\bar\omega_1-\bar\omega_9`,m`2\bar\omega_1+\bar\omega_2`,m`2\bar\omega_1-\bar\omega_8-\bar\omega_9`,m`3\bar\omega_1`,m`3\bar\omega_1-\bar\omega_7-\bar\omega_8-\bar\omega_9`,m`4\bar\omega_1+\bar\omega_2+\bar\omega_3`,m`4\bar\omega_1-\bar\omega_6-\bar\omega_7-\bar\omega_8-\bar\omega_9`,m`5\bar\omega_1-\bar\omega_5-\bar\omega_6-\bar\omega_7-\bar\omega_8-\bar\omega_9`])+m`<p>They are fundamental because every dominant weight has the expansion \(\sum_{a=1}^{8}p_a\Pi_a\) with the nonnegative integer coefficients</p>\[\begin{aligned}
p_1&=m_8-m_9,&p_2&=m_2-m_3,\\
p_3&=m_7-m_8,&p_4&=-m_2-m_3-m_4,\\
p_5&=m_6-m_7,&p_6&=m_3-m_4,\\
p_7&=m_5-m_6,&p_8&=m_4-m_5.
\end{aligned}\]`,note:m`<p>The middle column always uses sum-zero coefficients. In an alternative expression, a common constant may have been added to all nine coefficients, since the coordinate vectors sum to zero. For example, \(3\bar\omega_1\) has normalized coefficients \((8/3,-1/3,\ldots,-1/3)\).</p><p>The label formulas are inverse coordinates on the eight-dimensional sum-zero subspace. This avoids mistaking the nine symbols for nine independent weights.</p>`},
{n:31,part:11,p:81,title:'Type E, rank eight: the complete orbit inventory',type:'All eight source lists',text:m`<p>The weights of \(g_1\) are zero and the roots \(\omega_{ij},\pm\omega_{ijk}\). The weights of each remaining group are zero together with the reflection orbits specified below. The table retains every representative in the source, including the long list for \(g_8\) on p. 82.</p>`+orbitTable('E8'),note:m`<p>These are the author’s support claims for the fundamental representations, without multiplicities. The table deliberately does not turn orbit counts into dimensions.</p><p>Exact coordinate tests check the fundamental-label inversion and root reflections. They do not amount to a multiplicity computation for the large exceptional representations. The source’s short assertion of completeness of these long support lists is retained as an assertion dependent on the earlier procedure.</p>`},
{n:32,part:12,p:82,title:'Type F: short roots, long roots, and half-sums',type:'A rank-four calculation',text:m`<p>The roots are</p>\[\pm\bar\omega_i,\quad\pm\bar\omega_i\pm\bar\omega_j,\quad
\tfrac12(\pm\bar\omega_1\pm\bar\omega_2\pm\bar\omega_3\pm\bar\omega_4),\]<p>with distinct indices in each pair. The rank is \(4\), and the order is \(52\). For \(\varpi=\sum_{i=1}^{4}m_i\bar\omega_i\), the corresponding reflections are respectively</p>\[\begin{aligned}
S\varpi&=\varpi-2m_i\bar\omega_i,\\
S\varpi&=\varpi-(\pm m_i\pm m_j)(\pm\bar\omega_i\pm\bar\omega_j),\\
S\varpi&=\varpi-(\pm m_1\pm m_2\pm m_3\pm m_4)
\tfrac12(\pm\bar\omega_1\pm\bar\omega_2\pm\bar\omega_3\pm\bar\omega_4).
\end{aligned}\]<p>Signs match between the two factors in each expression. The coefficients are either all integers or all half-integers with odd numerators. Say that \(\varpi\) is higher than \(\varpi'\) if the first nonzero difference \(m_i-m'_i\), in index order, is positive. The necessary dominance conditions are</p>\[m_1\ge m_2\ge m_3\ge m_4\ge0,\qquad m_1\ge m_2+m_3+m_4.\]<p>Conversely, under these conditions repeated reflections never give a higher weight.</p>`+C('p. 80'),note:m`<p>Here the coordinate vectors may be taken orthonormal. The half-sum roots have squared length one, while the pair sums have squared length two; their reflection coefficients therefore differ in normalization.</p><p>The full sign choices give \(48\) roots. Adding the rank gives the order \(52\). The chamber has one additional wall beyond sorting and taking nonnegative coordinates.</p>`},
{n:33,part:12,p:83,title:'Type F: four fundamental weights and their supports',type:'The coordinate cone and all support layers',proof:'cartan13-proof-labels',text:m`<p>The fundamental dominant weights are</p>\[\Pi_1=\bar\omega_1,\quad \Pi_2=\bar\omega_1+\bar\omega_2,\quad
\Pi_3=\tfrac12(3\bar\omega_1+\bar\omega_2+\bar\omega_3+\bar\omega_4),\quad
\Pi_4=2\bar\omega_1+\bar\omega_2+\bar\omega_3.\]<p>Every dominant weight is their nonnegative integer combination, with</p>\[p_1=m_1-m_2-m_3-m_4,\quad p_2=m_2-m_3,\quad p_3=2m_4,\quad p_4=m_3-m_4.\]<p>The weights of \(g_1\) are zero and the boundary orbit of \(\bar\omega_1\). Those of \(g_2\) add the boundary orbit of \(\bar\omega_1+\bar\omega_2\). Those of \(g_3\) add the boundary orbit of \(\Pi_3\). Those of \(g_4\) contain zero, the boundary orbits of \(g_1,g_2,g_3\), the boundary orbit of \(g_1^2\), represented by \(2\bar\omega_1\), that of \(g_1g_2\), represented by \(2\bar\omega_1+\bar\omega_2\), and finally their own boundary orbit, represented by \(2\bar\omega_1+\bar\omega_2+\bar\omega_3\). In the established notation these lists are</p>`+orbitTable('F4'),note:m`<p>The superscript on \(g_1^2\) means the product of §10. It refers to the highest-weight component of two copies of \(g_1\), not their full tensor square.</p><p>The coefficient identities prove the label decomposition. The support lists still carry no multiplicity data; the variable counts announced in the introduction cannot be read off merely by counting these representatives.</p>`},
{n:34,part:13,p:84,title:'Type G: a two-dimensional chamber in three coordinates',type:'The final root model',figure:'g2',text:m`<p>The roots are</p>\[\pm\bar\omega_i,\quad\omega_{ij}=\bar\omega_i-\bar\omega_j\quad(i\ne j;\ 1\le i,j\le3),\qquad
\bar\omega_1+\bar\omega_2+\bar\omega_3=0.\]<p>The rank is \(2\), and the order is \(14\). Write</p>\[\varpi=m_1\bar\omega_1+m_2\bar\omega_2+m_3\bar\omega_3,\qquad m_1+m_2+m_3=0.\]<p>Then</p>\[\begin{aligned}
S_1\varpi&=\varpi-3m_1\bar\omega_1\\
&=\varpi-2m_1\bar\omega_1+m_1\bar\omega_2+m_1\bar\omega_3\\
&=-m_1\bar\omega_1-m_3\bar\omega_2-m_2\bar\omega_3,\\
S_{12}\varpi&=\varpi-(m_1-m_2)(\bar\omega_1-\bar\omega_2)\\
&=m_2\bar\omega_1+m_1\bar\omega_2+m_3\bar\omega_3.
\end{aligned}\]<p>The coefficients have denominators dividing three, with congruent numerators modulo three. Dominance requires</p>\[m_1\ge m_2\ge m_3,\qquad m_1\ge-m_3,\]<p>the last condition being equivalent to \(m_2\le0\). Conversely these conditions ensure that no equivalent weight is higher.</p>`+C('pp. 80–81'),note:m`<p>The coordinate vectors form an equilateral triple in a plane. The difference roots are longer by a factor of \(\sqrt3\). The reflection group has twelve transformations, generated by permutations of the coefficients and simultaneous negation.</p><p>The drawing shows the real weight plane, not a change from complex to real representations. Its two fundamental directions bound the chamber described by the coefficient inequalities.</p>`},
{n:35,part:13,p:84,title:'Type G: a coefficient misprint exposed by its own example',type:'Explicit correction to the original formula',proof:'cartan13-proof-labels',text:m`<p>The two fundamental dominant weights are</p>\[\Pi_1=\tfrac23\bar\omega_1-\tfrac13\bar\omega_2-\tfrac13\bar\omega_3=\bar\omega_1,\qquad
\Pi_2=\bar\omega_1-\bar\omega_3.\]<p>Every dominant weight is \(\varpi=p_1\Pi_1+p_2\Pi_2\), with</p>\[p_1=-3m_2,\qquad p_2=m_2-m_3.\]<p>The subscript in the first coefficient has been corrected from the printed \(m_3\) to \(m_2\). The weights of \(g_1\) are zero and the boundary weights \(\pm\bar\omega_i\), equivalent to \(\bar\omega_1\). The weights of \(g_2\) are zero, the boundary weights of \(g_1\), and its own boundary weights \(\bar\omega_i-\bar\omega_j\).</p>`,note:m`<p>For \(\Pi_2\), the normalized tuple is \((1,0,-1)\). The printed formula \(p_1=-3m_3\) gives \(p_1=3\), even though this weight is exactly \(\Pi_2\). The corrected formula gives \((p_1,p_2)=(0,1)\), and direct substitution verifies both coefficients for every sum-zero tuple.</p><p>Dominance makes the corrected coefficients nonnegative. The short-root reflection coefficient \(-3m_i\) and the long-root coefficient \(m_i-m_j\) make them integers. This completes the possible fundamental-weight labels; the source next turns to constructing the linear groups.</p>`}
);
export const passagesCartanWeights=rows.map(r=>({...r,id:'cartan13-'+r.n,label:'§'+r.n,printPage:r.p,sourceUrl:'https://www.numdam.org/article/BSMF_1913__41__53_1.pdf#page='+(r.p-51),sourceLabel:'French original · p. '+r.p,figureHtml:r.figure?figuresCartanWeights[r.figure]:undefined,figure:undefined}));
const titles=['Generalities: weights and equivalent weights','Same structure and the same highest weight','The product of two linear realizations','The fundamental linear groups','Fundamental weights of type A','Fundamental weights of type B','Fundamental weights of type C','Fundamental weights of type D','Fundamental weights of type E, rank six','Fundamental weights of type E, rank seven','Fundamental weights of type E, rank eight','Fundamental weights of type F','Fundamental weights of type G'];
const roman=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XIII'];
export const sectionsCartanWeights=titles.map((title,i)=>{const selected=passagesCartanWeights.filter(r=>r.part===i+1);return {id:'cartan13-part-'+(i+1),title,range:roman[i]+' · '+(selected.length===1?'§'+selected[0].n:'§§'+selected[0].n+'–'+selected.at(-1).n),rows:selected};});
